function countMirrors(s: string): number {
  let count = 0;
  for (let i = 0; i < s.length; i++)
    for (let j = i; j < s.length; j++) {
      let a = i, b = j;
      while (a < b && s[a] === s[b]) { a++; b--; }
      if (a >= b) count++;
    }
  return count;
}

