function countMirrors(s: string): number {
  const n = s.length;
  const mir: boolean[][] = Array.from({ length: n }, () => new Array<boolean>(n).fill(false));
  let count = 0;
  for (let L = 1; L <= n; L++)
    for (let i = 0; i + L - 1 < n; i++) {
      const j = i + L - 1;
      mir[i][j] = s[i] === s[j] && (L <= 2 || mir[i + 1][j - 1]);
      if (mir[i][j]) count++;
    }
  return count;
}

