  const n = s.length;
  let count = 0;
  for (let c = 0; c < n; c++) {
    for (let [lo, hi] of [[c, c], [c, c + 1]]) { // odd centre, even centre
      while (lo >= 0 && hi < n && s[lo] === s[hi]) { count++; lo--; hi++; }
    }
  }
  return count;
}

